    15	  RankingParams,
    16	} from '@/types/novel';
    17	
    18	// 获取小说列表
    19	export async function getNovels(params: NovelListParams = {}): Promise<PaginatedResponse<Novel>> {
    20	  const queryString = buildQueryString(params);
    21	  const response = await get<PaginatedResponse<Novel>>(`/novels${queryString}`, false);
    22	  return response;
    23	}
    24	
    25	// 获取单部小说详情
    26	export async function getNovel(id: number): Promise<Novel> {
    27	  const response = await get<ApiResponse<Novel>>(`/novels/${id}`, false);
    28	  return response.data;
    29	}
